def process_order(order):
    if order is None:
        return None
    if order['status'] != 'pending':
        return None
    if order['items'] is None or len(order['items']) == 0:
        return None
    if order['user_id'] is None:
        return None
    total = 0
    for item in order['items']:
        if item['price'] is None:
            return None
        if item['quantity'] is None:
