    if user_type == 'student':
        discount = 0.2
        if is_member:
            discount = 0.25
            if years_active > 5:
                discount = 0.3
    elif user_type == 'senior':
        discount = 0.15
        if is_member:
            discount = 0.2
            if years_active > 5:
                discount = 0.25
    elif user_type == 'regular':
