DISCOUNT_TABLE = {
    'student': {'base': 0.20, 'member': 0.05, 'loyal': 0.05},
    'senior':  {'base': 0.15, 'member': 0.05, 'loyal': 0.05},
    'regular': {'base': 0.00, 'member': 0.10, 'loyal': 0.05},
}

def calculate_discount(price: float, user_type: str, is_member: bool, years_active: int) -> float:
    rates = DISCOUNT_TABLE.get(user_type, {'base': 0.0, 'member': 0.0, 'loyal': 0.0})
    discount = rates['base']
    if is_member:
        discount += rates['member']
        if years_active > 5:
            discount += rates['loyal']
    return price * (1 - discount)

