from abc import ABC, abstractmethod

class Animal(ABC):
    def __init__(self, name: str):
        self.name = name

    @abstractmethod
    def speak(self) -> str: ...

    @abstractmethod
    def move(self) -> str: ...

class Dog(Animal):
    def speak(self) -> str:
        return f'{self.name} says Woof'
    def move(self) -> str:
        return f'{self.name} runs'

class Cat(Animal):
    def speak(self) -> str:
        return f'{self.name} says Meow'
    def move(self) -> str:
        return f'{self.name} slinks'

class Cow(Animal):
    def speak(self) -> str:
        return f'{self.name} says Moo'
    def move(self) -> str:
