class NotificationService:
    def __init__(self, emailer, sms):
        self.emailer = emailer
        self.sms = sms

    def welcome(self, user: dict) -> None:
        self.emailer.send(user['email'], 'Welcome!')
        self.sms.send(user['phone'], 'Welcome!')

    def deactivation(self, user: dict) -> None:
        self.emailer.send(user['email'], 'Account deactivated')


class UserService:
    def __init__(self, repo: UserRepository, notifications: NotificationService, logger, analytics):
        self.repo = repo
        self.notifications = notifications
        self.logger = logger
        self.analytics = analytics

    def register(self, name: str, email: str, phone: str) -> dict:
        user = {'id': self.repo.next_id(), 'name': name, 'email': email, 'phone': phone}
        self.repo.save(user)
        self.notifications.welcome(user)
        self.logger.log(f'Registered {name}')
        self.analytics.track('register', user)
        return user

    def deactivate(self, user_id: int) -> dict:
        user = self.repo.find(user_id)
        user['active'] = False
        self.repo.save(user)
        self.notifications.deactivation(user)
        self.logger.log(f'Deactivated {user_id}')
        self.analytics.track('deactivate', user)
        return user

