def _coerce_value(raw: str):
    stripped = raw.strip()
    low = stripped.lower()
    if low == 'true':
        return True
    if low == 'false':
        return False
    try:
        return int(stripped)
    except ValueError:
        pass
    try:
        return float(stripped)
    except ValueError:
        return stripped

def _config_lines(path: str):
    with open(path) as f:
        for line in f:
            line = line.strip()
            if line and not line.startswith('#') and '=' in line:
                yield line

def parse_config(path: str) -> dict:
    return {
        (parts := line.split('=', 1))[0].strip(): _coerce_value(parts[1])
        for line in _config_lines(path)
    }

