import json
import os
from typing import Optional

class JsonFileRepository:
    def __init__(self, path: str):
        self.path = path
        self._data: list = self._load()

    def _load(self) -> list:
        if not os.path.exists(self.path):
            return []
        with open(self.path) as f:
            return json.load(f)

    def _flush(self) -> None:
        with open(self.path, 'w') as f:
            json.dump(self._data, f, indent=2)

    def _next_id(self) -> int:
        return max((u['id'] for u in self._data), default=0) + 1

    def add(self, name: str, email: str) -> dict:
        user = {'id': self._next_id(), 'name': name, 'email': email}
        self._data.append(user)
        self._flush()
        return user

    def remove(self, user_id: int) -> None:
        self._data = [u for u in self._data if u['id'] != user_id]
        self._flush()

    def find_by_email(self, email: str) -> Optional[dict]:
        return next((u for u in self._data if u['email'] == email), None)

    def all(self) -> list:
        return list(self._data)

