import json as _json
from typing import Protocol

class Renderer(Protocol):
    def render(self, data: list[dict]) -> str: ...

class CsvRenderer:
    def render(self, data: list[dict]) -> str:
        if not data:
            return ''
        header = ','.join(data[0].keys())
        rows = [','.join(str(v) for v in row.values()) for row in data]
        return '\n'.join([header] + rows)

class JsonRenderer:
    def render(self, data: list[dict]) -> str:
        return _json.dumps(data, indent=2)

class HtmlRenderer:
    def render(self, data: list[dict]) -> str:
        if not data:
            return '<table></table>'
        headers = ''.join(f'<th>{k}</th>' for k in data[0].keys())
        rows = ''.join(
            '<tr>' + ''.join(f'<td>{v}</td>' for v in row.values()) + '</tr>'
            for row in data
        )
        return f'<table><thead><tr>{headers}</tr></thead><tbody>{rows}</tbody></table>'

FORMAT_REGISTRY: dict[str, Renderer] = {
    'csv':  CsvRenderer(),
    'json': JsonRenderer(),
    'html': HtmlRenderer(),
}

class ReportGenerator:
    def generate(self, data: list[dict], format: str) -> str:
        renderer = FORMAT_REGISTRY.get(format)
        if renderer is None:
            raise ValueError(f'Unknown format: {format}')
        return renderer.render(data)

