import json
import urllib.request
from typing import Optional

def fetch(url: str) -> str:
    response = urllib.request.urlopen(url)
    return response.read().decode('utf-8')

def parse(raw: str) -> list[dict]:
    return json.loads(raw)

def transform(items: list[dict]) -> list[dict]:
    result = [
        {
            'id': item['id'],
            'name': item['name'].strip().title(),
            'score': round(item.get('score', 0), 2),
        }
        for item in items
        if item.get('active')
    ]
    return sorted(result, key=lambda x: x['score'], reverse=True)

def fetch_and_process(url: str) -> list[dict]:
    try:
        raw = fetch(url)
    except OSError as e:
        raise ConnectionError(f'Failed to fetch {url}') from e
    try:
        items = parse(raw)
    except json.JSONDecodeError as e:
        raise ValueError(f'Invalid JSON from {url}') from e
    return transform(items)

