def run_etl(source_path, dest_path):
    import csv, json, os
    # Read
    records = []
    with open(source_path) as f:
        reader = csv.DictReader(f)
        for row in reader:
            records.append(row)
    # Transform
    transformed = []
    for r in records:
        try:
            transformed.append({
                'id': int(r['id']),
                'name': r['name'].strip().title(),
                'age': int(r['age']),
                'score': float(r['score']),
                'active': r['active'].lower() == 'true'
            })
        except (KeyError, ValueError):
            continue
    # Write
    os.makedirs(os.path.dirname(dest_path), exist_ok=True)
    with open(dest_path, 'w') as f:
        json.dump(transformed, f, indent=2)
    return len(transformed)

