import csv
import json
import os
from typing import Optional

def extract(source_path: str) -> list[dict]:
    with open(source_path, newline='', encoding='utf-8') as f:
        return list(csv.DictReader(f))

def transform_record(row: dict) -> Optional[dict]:
    try:
        return {
            'id':     int(row['id']),
            'name':   row['name'].strip().title(),
            'age':    int(row['age']),
            'score':  float(row['score']),
            'active': row['active'].lower() == 'true',
        }
    except (KeyError, ValueError):
        return None

def load(records: list[dict], dest_path: str) -> None:
    os.makedirs(os.path.dirname(dest_path) or '.', exist_ok=True)
    with open(dest_path, 'w', encoding='utf-8') as f:
        json.dump(records, f, indent=2)

def run_etl(source_path: str, dest_path: str) -> int:
    raw = extract(source_path)
    transformed = [r for row in raw if (r := transform_record(row)) is not None]
    load(transformed, dest_path)
    return len(transformed)

