import asyncio
from collections import defaultdict
from typing import Callable

class EventSystem:
    def __init__(self):
        self.listeners: defaultdict[str, list[Callable]] = defaultdict(list)

    def on(self, event: str, callback: Callable) -> None:
        self.listeners[event].append(callback)

    def off(self, event: str, callback: Callable) -> None:
        self.listeners[event] = [cb for cb in self.listeners[event] if cb != callback]
        if not self.listeners[event]:
            del self.listeners[event]

    def emit(self, event: str, *args, **kwargs) -> None:
        for callback in list(self.listeners.get(event, [])):
            callback(*args, **kwargs)

    def once(self, event: str, callback: Callable) -> None:
        def wrapper(*args, **kwargs):
            self.off(event, wrapper)
            callback(*args, **kwargs)
        self.on(event, wrapper)

    async def emit_async(self, event: str, *args, **kwargs) -> None:
        coros = []
        for callback in list(self.listeners.get(event, [])):
            result = callback(*args, **kwargs)
            if asyncio.iscoroutine(result):
                coros.append(result)
        if coros:
            await asyncio.gather(*coros)

    def listener_count(self, event: str) -> int:
        return len(self.listeners.get(event, []))

