import asyncio
from dataclasses import dataclass, field
from typing import Any, Callable, Optional

@dataclass
class TaskResult:
    func_name: str
    status: str
    result: Any = None
    error: Optional[str] = None

    @property
    def ok(self) -> bool:
        return self.status == 'ok'

class TaskRunner:
    def __init__(self):
        self._tasks: list[tuple[Callable, tuple, dict]] = []
        self._results: list[TaskResult] = []

    def add_task(self, func: Callable, *args, **kwargs) -> None:
        self._tasks.append((func, args, kwargs))

    def _execute(self, func: Callable, args: tuple, kwargs: dict) -> TaskResult:
        try:
            return TaskResult(func_name=func.__name__, status='ok', result=func(*args, **kwargs))
        except Exception as e:
            return TaskResult(func_name=func.__name__, status='error', error=str(e))

    def run(self) -> list[TaskResult]:
        self._results = [self._execute(f, a, kw) for f, a, kw in self._tasks]
        return self._results

    async def run_async(self) -> list[TaskResult]:
        async def _run_one(func, args, kwargs):
            try:
                result = func(*args, **kwargs)
                if asyncio.iscoroutine(result):
                    result = await result
                return TaskResult(func_name=func.__name__, status='ok', result=result)
            except Exception as e:
                return TaskResult(func_name=func.__name__, status='error', error=str(e))
        self._results = list(await asyncio.gather(*[_run_one(f, a, kw) for f, a, kw in self._tasks]))
        return self._results

    @property
    def summary(self) -> dict:
        ok = [r for r in self._results if r.ok]
        err = [r for r in self._results if not r.ok]
        return {'total': len(self._results), 'succeeded': len(ok), 'failed': len(err), 'errors': [{'func': r.func_name, 'error': r.error} for r in err]}
